function fibonacci($start, $end) {
 $arr = array(0, 1);
 for ($i = 2; $i < $end; $i++) {
 $arr[$i] = $arr[$i-1] + $arr[$i-2];
 if ($arr[$i] > $end) break;
 }
 $arr = array_slice($arr, $start+1);
 return $arr;
}
function isPrime($n) {
 if ($n <= 1) return false;
 for ($i = 2; $i <= sqrt($n); $i++) {
 if ($n % $i == 0) return false;
 }
 return true;
}
function sumOfPrimes($n) {
 $sum = 0;
 $count = 0;
 for ($i = 2; $count < $n; $i++) {
 if (isPrime($i)) {
 $sum += $i;
 $count++;
 }
 }
 return $sum;

