php
$components = array(
 array("Blades", 10, 500),
 array("Rotor", 1, 2000),
 array("Shaft", 1, 1000),
 array("Generator", 1, 5000),
 array("Gearbox", 1, 3000),
 array("Controller", 1, 1500),
 array("Nacelle", 1, 2500)
);
$tax_rate = 0.07;
$total_cost = 0;
foreach ($components as $component) {
 $component_cost = $component[1] * $component[2];
 $total_cost += $component_cost;
 echo $component[0] . ": $" . $component_cost . "<br";
}
$tax = $total_cost * $tax_rate;
$total_cost += $tax;
echo "Total cost: $" . $total_cost . ", including $" . $tax . " in taxes.";
?> 
