{
 if (a_count == 0 && b_count == 0) {
 cout << str << endl;
 return;
 }

 if (a_count > 0) {
 generate_strings(str + "a", a_count - 1, b_count);
 }

 if (b_count > a_count) {
 generate_strings(str + "b", a_count, b_count - 1);
 }
}
