```javascript
function rearrangeNumbers() {
 const numbers = [1, 3, 5, 7, 9, 11, 13];
 let rearrangedNumbers = [];

 for (let i = 0; i < numbers.length; i++) {
 if (i + 2 < numbers.length && numbers[i] + numbers[i+1] + numbers[i+2] === 21) {
 rearrangedNumbers.push(numbers[i+1], numbers[i+2], numbers[i]);
 i += 2;
 } else {
 rearrangedNumbers.push(numbers[i]);
 }
 }

 const sumFirstFour = rearrangedNumbers.slice(0, 4).reduce((a, b) => a + b, 0);
 const sumLastFour = rearrangedNumbers.slice(-4).reduce((a, b) => a + b, 0);

 if (sumFirstFour === sumLastFour) {
 const list = document.getElementById("odd-numbers");
 list.innerHTML = "";

 for (let i = 0; i < rearrangedNumbers.length; i++) {
 const item = document.createElement("li");
 item.innerText = rearrangedNumbers[i];
 list.appendChild(item);
 }
 } else {
 alert("Unable to rearrange numbers as specified.");
 }
}
```
