```python
import pandas as pd
import json
# Read the Excel table
df = pd.read_excel('words.xlsx', index_col=None)
# Define the categories and subcategories
categories = {
 'Computer peripherals': {
 'Input Devices': [],
 'Output Devices': []
 },
 'Electronic devices': {
 'Personal Devices': [],
 'Household Devices': []
 }
}
# Categorize the words
for word in df['Words']:
 if word in ['Keyboard', 'Mouse']:
 categories['Computer peripherals']['Input Devices'].append(word)
 elif word in ['Monitor', 'Printer']:
 categories['Computer peripherals']['Output Devices'].append(word)
 elif word in ['Smartphone', 'Tablet', 'Smartwatch']:
 categories['Electronic devices']['Personal Devices'].append(word)
