 wordScores[item.term] = item.tfidf;
});
// Sentiment analysis
const SentimentAnalyzer = natural.SentimentAnalyzer;
const stemmer = natural.PorterStemmer;
const analyzer = new SentimentAnalyzer('English', stemmer, 'afinn');
const sentiment = analyzer.getSentiment(tokens);
// Training the classifier
classifier.addDocument(stemmedTokens, sentiment);
// Applying the selected algorithm for classification
classifier.train();
const category = classifier.classify(stemmedTokens);
// Output the result
console.log(`The text "${text}" is classified as ${category}`);
```
