public class CircularPathDisplacement {
 public static void main(String[] args) {
 double radius = 10; // radius of the circular path
 double pi = 3.14; // value of pi
 double displacement; // variable to store the displacement

 // table of values for velocity and time
 double[][] table = {{5, 10}, {3, 8}, {7, 5}};

